-- Adds the PayPal invoicing tables to an EXISTING Akanti database.
-- Safe to run once. Wrap in a transaction; roll back on error.
BEGIN;

CREATE TABLE "PayPalWebhookEvents" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "PayPalEventId" character varying(64) NOT NULL,
    "EventType" character varying(80) NOT NULL,
    "ResourceType" character varying(80),
    "RawPayload" text NOT NULL,
    "SignatureVerified" boolean NOT NULL,
    "ProcessedAt" timestamp with time zone,
    "ProcessingError" character varying(1000),
    "ReceivedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_PayPalWebhookEvents" PRIMARY KEY ("Id")
);

CREATE TABLE "Customers" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL,
    "Name" character varying(200) NOT NULL,
    "Email" character varying(320) NOT NULL,
    "Phone" character varying(40),
    "PayPalCustomerId" character varying(64),
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_Customers" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Customers_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Invoices" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL,
    "CustomerId" integer NOT NULL,
    "Number" character varying(64) NOT NULL,
    "Status" integer NOT NULL,
    "Currency" character varying(3) NOT NULL,
    "Subtotal" numeric(18,2) NOT NULL,
    "Tax" numeric(18,2) NOT NULL,
    "Total" numeric(18,2) NOT NULL,
    "IssueDate" timestamp with time zone NOT NULL,
    "DueDate" timestamp with time zone NOT NULL,
    "Notes" character varying(1000),
    "PayPalInvoiceId" character varying(64),
    "PayPalStatus" character varying(40),
    "RecipientViewUrl" character varying(500),
    "PaidAt" timestamp with time zone,
    "IncomeId" integer,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_Invoices" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Invoices_Customers_CustomerId" FOREIGN KEY ("CustomerId") REFERENCES "Customers" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Invoices_Incomes_IncomeId" FOREIGN KEY ("IncomeId") REFERENCES "Incomes" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_Invoices_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "InvoiceDrafts" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL,
    "Status" integer NOT NULL,
    "MessagesJson" text NOT NULL,
    "ProposedInvoiceJson" text,
    "InvoiceId" integer,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
    CONSTRAINT "PK_InvoiceDrafts" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_InvoiceDrafts_Invoices_InvoiceId" FOREIGN KEY ("InvoiceId") REFERENCES "Invoices" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_InvoiceDrafts_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "InvoiceItems" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "InvoiceId" integer NOT NULL,
    "Description" character varying(500) NOT NULL,
    "Quantity" numeric(18,2) NOT NULL,
    "UnitPrice" numeric(18,2) NOT NULL,
    "LineTotal" numeric(18,2) NOT NULL,
    CONSTRAINT "PK_InvoiceItems" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_InvoiceItems_Invoices_InvoiceId" FOREIGN KEY ("InvoiceId") REFERENCES "Invoices" ("Id") ON DELETE CASCADE
);

CREATE UNIQUE INDEX "IX_Customers_UserId_Email" ON "Customers" ("UserId", "Email") WHERE "IsDeleted" = false;

CREATE INDEX "IX_InvoiceDrafts_InvoiceId" ON "InvoiceDrafts" ("InvoiceId");

CREATE INDEX "IX_InvoiceDrafts_UserId_Status_UpdatedAt" ON "InvoiceDrafts" ("UserId", "Status", "UpdatedAt");

CREATE INDEX "IX_InvoiceItems_InvoiceId" ON "InvoiceItems" ("InvoiceId");

CREATE INDEX "IX_Invoices_CustomerId" ON "Invoices" ("CustomerId");

CREATE INDEX "IX_Invoices_IncomeId" ON "Invoices" ("IncomeId");

CREATE UNIQUE INDEX "IX_Invoices_PayPalInvoiceId" ON "Invoices" ("PayPalInvoiceId") WHERE "PayPalInvoiceId" IS NOT NULL;

CREATE UNIQUE INDEX "IX_Invoices_UserId_Number" ON "Invoices" ("UserId", "Number") WHERE "IsDeleted" = false;

CREATE INDEX "IX_Invoices_UserId_Status_DueDate_IsDeleted" ON "Invoices" ("UserId", "Status", "DueDate", "IsDeleted");

CREATE UNIQUE INDEX "IX_PayPalWebhookEvents_PayPalEventId" ON "PayPalWebhookEvents" ("PayPalEventId");

CREATE INDEX "IX_PayPalWebhookEvents_ProcessedAt_ReceivedAt" ON "PayPalWebhookEvents" ("ProcessedAt", "ReceivedAt");

COMMIT;
